pub type Named[T] = { name: Str; value: T; }

impl Deref for Named[T] {
  type Target = T;

  fn deref(self: &Named[T]) -> &T {
    return &self.value;
  }
}

fn main() -> Int {
  let score = Named[Int]{ name: "score", value: 100 };
  return *score;
}
